app.post('/analisar', requireAuth, upload.single('arquivo'), async (req, res) => {
  const url = String(req.body.url || '').trim();
  const arquivoUpload = req.file;
  if (!url && !arquivoUpload) return res.status(400).json({ erro: 'Cola o link do video ou anexa um arquivo.' });
  if (!GROQ_API_KEY) return res.status(500).json({ erro: 'GROQ_API_KEY nao configurada no servidor.' });
  if (!GEMINI_API_KEY) return res.status(500).json({ erro: 'GEMINI_API_KEY nao configurada no servidor.' });

  let pasta = null;
  const limparUpload = () => { if (arquivoUpload && fs.existsSync(arquivoUpload.path)) { try { fs.unlinkSync(arquivoUpload.path); } catch (e) {} } };
  try {
    // CRITICO: garantir que yt-dlp e ffmpeg estao baixados/disponiveis
    if (!arquivoUpload) await garantirYtdlp();
    await garantirFfmpeg();

    pasta = fs.mkdtempSync(path.join(os.tmpdir(), 'cortador-analise-'));
    const videoPath = path.join(pasta, 'video.mp4');
    const audioPath = path.join(pasta, 'audio.mp3');

    // Decide a fonte do video
    let fullPath;
    if (arquivoUpload) {
      // Upload de arquivo: usa direto
      console.log('[cortador-analisar] usando arquivo enviado:', arquivoUpload.originalname, '|', (arquivoUpload.size/1024/1024).toFixed(1), 'MB');
      fullPath = arquivoUpload.path;
    } else {
      // YouTube: baixa (usa cache existente)
      const cachePath = cachePathPara(url, '.mp4');
      if (fs.existsSync(cachePath) && (Date.now() - fs.statSync(cachePath).mtimeMs) < CACHE_TTL_MS) {
        console.log('[cortador-analisar] usando video do cache');
        fullPath = cachePath;
      } else {
        console.log('[cortador-analisar] baixando video...');
        const FMT_HQ = 'bv*[height<=1080]+ba/b[height<=1080]/bv*+ba/best';
        const estrategias = [
          'youtube:player_client=tv,web_safari',
          'youtube:player_client=web_safari,default',
          'youtube:player_client=ios',
          'youtube:player_client=tv_embedded,android',
          'youtube:player_client=mweb',
        ];
        let ultimoErro = '';
        let ok = false;
        for (const ext of estrategias) {
          console.log('[cortador-analisar] yt-dlp tentando:', ext);
          const r = await executar(YTDLP, [
            '--no-playlist', '--no-warnings', '--no-progress',
            '--extractor-args', ext,
            ...(cookiesOk ? ['--cookies', COOKIES_PATH] : []),
            ...(PROXY_URL ? ['--proxy', PROXY_URL] : []),
            '--ffmpeg-location', FFMPEG,
            '-N', '4',
            '-f', FMT_HQ,
            '--merge-output-format', 'mp4',
            '-o', videoPath,
            url,
          ], 'yt-dlp-analise');
          if (r.codigo === 0 && fs.existsSync(videoPath) && fs.statSync(videoPath).size > 1024 * 1024) {
            ok = true;
            console.log('[cortador-analisar] yt-dlp OK com', ext);
            break;
          }
          ultimoErro = (r.stderr || r.stdout || '').slice(-300);
          console.log('[cortador-analisar] tentativa falhou:', ultimoErro.slice(-200));
          try { if (fs.existsSync(videoPath)) fs.unlinkSync(videoPath); } catch (e) {}
        }
        let cobaltErro = '';
        if (!ok && COBALT_API_URL) {
          console.log('[cortador-analisar] yt-dlp falhou em todas, tentando Cobalt...');
          try {
            await baixarViaCobalt(url, videoPath);
            if (fs.existsSync(videoPath) && fs.statSync(videoPath).size > 1024 * 1024) {
              ok = true;
              console.log('[cortador-analisar] Cobalt OK');
            }
          } catch (e) {
            cobaltErro = e.message;
            console.log('[cortador-analisar] Cobalt falhou:', cobaltErro);
          }
        }
        if (!ok) {
          limpar(pasta);
          return res.status(500).json({
            erro: 'Nao consegui baixar esse video do YouTube. Tenta com upload de arquivo (botao "Arquivo" acima).',
            detalhe: 'yt-dlp: ' + ultimoErro + '\n\ncobalt: ' + cobaltErro
          });
        }
        try { fs.copyFileSync(videoPath, cachePath); } catch (e) {}
        fullPath = videoPath;
      }
    }

    // 2. Extrair audio leve pra mandar pro Groq
    console.log('[cortador-analisar] extraindo audio...');
    const t1 = Date.now();
    await extrairAudio(fullPath, audioPath);
    const tamAudio = fs.statSync(audioPath).size;
    console.log('[cortador-analisar] audio extraido em', ((Date.now()-t1)/1000).toFixed(1), 's |', (tamAudio/1024/1024).toFixed(1), 'MB');

    // Groq tem limite de 40MB por arquivo
    if (tamAudio > 39 * 1024 * 1024) {
      limpar(pasta);
      return res.status(400).json({ erro: 'Esse video e muito longo pra analise por IA (limite ~5h de audio).' });
    }

    // 3. Pegar duracao total do video (via ffprobe)
    let duracaoTotal = 0;
    try {
      const probe = await executar(FFMPEG, ['-i', fullPath, '-hide_banner'], 'ffprobe-dur');
      const m = (probe.stderr || '').match(/Duration:\s*(\d+):(\d+):(\d+\.\d+)/);
      if (m) duracaoTotal = parseInt(m[1])*3600 + parseInt(m[2])*60 + parseFloat(m[3]);
    } catch (e) {}
    console.log('[cortador-analisar] duracao total:', duracaoTotal.toFixed(0), 's');

    // 4. Transcrever com Groq
    console.log('[cortador-analisar] transcrevendo com Groq...');
    const t2 = Date.now();
    const transcricao = await transcreverComGroq(audioPath);
    console.log('[cortador-analisar] transcricao em', ((Date.now()-t2)/1000).toFixed(1), 's');

    // 5. Analisar com Gemini
    console.log('[cortador-analisar] analisando com Gemini...');
    const t3 = Date.now();
    const momentos = await analisarComGemini(transcricao, duracaoTotal);
    console.log('[cortador-analisar] analise em', ((Date.now()-t3)/1000).toFixed(1), 's');

    // 6. Limpar e retornar
    limpar(pasta);
    // Mantem arquivo upload pro gerarShortDoMomento usar depois (vai limpar quando expirar)
    res.json({
      ok: true,
      url: url || null,
      arquivo_upload_id: arquivoUpload ? path.basename(arquivoUpload.path) : null,
      duracao_total: duracaoTotal,
      transcricao_chars: (transcricao.text || '').length,
      momentos: momentos
    });
  } catch (e) {
    console.error('[cortador-analisar] erro:', e.message);
    if (pasta) limpar(pasta);
    limparUpload();
    res.status(500).json({ erro: 'Erro analisando: ' + e.message });
  }
});


const PORTA = process.env.PORT || 3000;
app.listen(PORTA, () => console.log('Cortador rodando na porta ' + PORTA));
